/** Decorative sidebar icon for the work-card panel row. */

/**
 * Render the panel glyph at the size the Sidebar requests; the Sidebar owns the
 * navigation label, so the glyph itself is decorative.
 * @param props.size - requested square edge in pixels.
 * @returns the card-stack glyph.
 */
export function PmPanelIcon({ size }: { readonly size: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none" aria-hidden="true" focusable="false">
      <rect x="2" y="2.5" width="12" height="3.6" rx="1.1" stroke="currentColor" strokeWidth="1.3" />
      <rect x="2" y="7.4" width="12" height="3.6" rx="1.1" stroke="currentColor" strokeWidth="1.3" />
      <path d="M4.4 13.3h7.2" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" />
    </svg>
  )
}
